#include<bits/stdc++.h>

using namespace std;
using ll=long long;
using pl=pair<ll,ll>;

ll solve(vector<ll> &v7,vector<ll> &v5,vector<ll> &v3){
  ll res=ssize(v7);
  res*=ssize(v5);
  res*=ssize(v3);
  if(res==0){return 0;}

  vector<pl> vp;
  for(auto &nx : v7){vp.push_back({nx,7});}
  for(auto &nx : v5){vp.push_back({nx,5});}
  for(auto &nx : v3){vp.push_back({nx,3});}
  sort(vp.begin(),vp.end());
  ll p7=0,s7=v7.size();
  ll p3=0,s3=v3.size();
  for(auto &nx : vp){
    if(nx.second==7){
      p7++; s7--;
    }
    else if(nx.second==5){
      res-=p7*s3;
      res-=p3*s7;
    }
    else if(nx.second==3){
      p3++; s3--;
    }
  }
  return res;
}

int main(){
  ll n;
  cin >> n;
  map<pl,vector<ll>> mp;
  set<ll> tst;
  for(ll i=0;i<n;i++){
    ll a;
    cin >> a;
    if(a%7==0){
      mp[{a/7,7}].push_back(i);
      tst.insert(a/7);
    }
    if(a%5==0){mp[{a/5,5}].push_back(i);}
    if(a%3==0){mp[{a/3,3}].push_back(i);}
  }
  ll res=0;
  for(auto &nx : tst){
    res+=solve(mp[{nx,7}],mp[{nx,5}],mp[{nx,3}]);
  }
  cout << res << "\n";
  return 0;
}

#include <iostream>
#include <vector>
#include <map>
#include <ranges>

int main() {
    using namespace std;
    // i < j, k < j を数え上げる関数
    const auto solve{[](const auto& seq) {
        map<unsigned, unsigned> three, seven;
        unsigned long ans{};
        for (const auto x : seq) {
            if (x % 3 == 0)
                ++three[x / 3];
            if (x % 7 == 0)
                ++seven[x / 7];
            if (x % 5 == 0)
                ans += three.contains(x / 5) && seven.contains(x / 5) ? static_cast<unsigned long>(three[x / 5]) * seven[x / 5] : 0;
        }
        return ans;
    }};
    const auto A{views::istream<unsigned>(cin) | views::drop(1) | ranges::to<vector<unsigned>>()};
    // 順方向と逆方向を解き、足し合わせる
    cout << solve(A) + solve(A | views::reverse) << endl;
    return 0;
}
